import { useState, useEffect } from 'react';

interface Todo {
  id: number;
  text: string;
  completed: boolean;
}

// Mock API functions
const api = {
  fetchTodos: async (): Promise<Todo[]> => {
    await new Promise(resolve => setTimeout(resolve, 500));
    return [
      { id: 1, text: 'Learn React', completed: true },
      { id: 2, text: 'Build a project', completed: false },
    ];
  },

  addTodo: async (text: string): Promise<Todo> => {
    await new Promise(resolve => setTimeout(resolve, 800));
    // 30% chance of failure
    if (Math.random() < 0.3) {
      throw new Error('Server error: Could not add todo');
    }
    return { id: Date.now(), text, completed: false };
  },

  deleteTodo: async (id: number): Promise<void> => {
    await new Promise(resolve => setTimeout(resolve, 500));
    // 20% chance of failure
    if (Math.random() < 0.2) {
      throw new Error('Server error: Could not delete todo');
    }
  },
};

export default function AsyncTodoList() {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    loadTodos();
  }, []);

  const loadTodos = async () => {
    try {
      const data = await api.fetchTodos();
      setTodos(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load todos');
    } finally {
      setLoading(false);
    }
  };

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim()) return;

    const tempId = Date.now();
    const optimisticTodo: Todo = { id: tempId, text: input, completed: false };

    // Optimistic update
    setTodos(prev => [...prev, optimisticTodo]);
    setInput('');
    setSubmitting(true);

    try {
      const newTodo = await api.addTodo(input);
      // Replace temp with real todo
      setTodos(prev => prev.map(t => t.id === tempId ? newTodo : t));
      setError(null);
    } catch (err) {
      // Rollback on error
      setTodos(prev => prev.filter(t => t.id !== tempId));
      setError(err instanceof Error ? err.message : 'Failed to add todo');
      setInput(optimisticTodo.text); // Restore input
    } finally {
      setSubmitting(false);
    }
  };

  const handleDelete = async (id: number) => {
    const todoToDelete = todos.find(t => t.id === id);
    if (!todoToDelete) return;

    // Optimistic delete
    setTodos(prev => prev.filter(t => t.id !== id));

    try {
      await api.deleteTodo(id);
      setError(null);
    } catch (err) {
      // Rollback on error
      setTodos(prev => [...prev, todoToDelete]);
      setError(err instanceof Error ? err.message : 'Failed to delete todo');
    }
  };

  if (loading) {
    return <div className="loading">Loading todos...</div>;
  }

  return (
    <div className="todo-container">
      <h1>Async Todo List</h1>

      {error && (
        <div className="error-banner">
          {error}
          <button onClick={() => setError(null)}>Dismiss</button>
        </div>
      )}

      <form onSubmit={handleAdd}>
        <input
          type="text"
          placeholder="Add a new todo"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          disabled={submitting}
        />
        <button type="submit" disabled={submitting}>
          {submitting ? 'Adding...' : 'Add'}
        </button>
      </form>

      <ul className="todo-list">
        {todos.map(todo => (
          <li key={todo.id} className="todo-item">
            <span className={todo.completed ? 'completed' : ''}>{todo.text}</span>
            <button onClick={() => handleDelete(todo.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}
